<script setup lang="ts">import { onMounted, ref, watch } from 'vue';import { useRoute } from 'vue-router';import { searchKnowledge } from '../services/api';import type { SearchResult } from '../types/api';const route=useRoute();const results=ref<SearchResult[]>([]);const isLoading=ref(false);const filters=ref({type:'',tag:''});async function load(){const q=String(route.query.q||'');if(!q)return;isLoading.value=true;try{results.value=(await searchKnowledge(q,filters.value)).items}catch{results.value=[]}finally{isLoading.value=false}}onMounted(load);watch([()=>route.query.q,filters],load,{deep:true});</script>
<template><header class="page-head"><div><h1 class="page-title">搜索结果</h1><span class="muted">“{{ $route.query.q }}”</span></div></header><div style="display:flex;gap:18px"><aside class="desktop-only" style="width:190px"><el-select v-model="filters.type" placeholder="内容类型" clearable><el-option label="全部" value=""/><el-option label="文档" value="document"/></el-select></aside><section style="flex:1"><el-skeleton v-if="isLoading" :rows="5" animated/><el-empty v-else-if="!results.length" description="没有匹配的知识"/><el-card v-for="item in results" :key="item.id" style="margin-bottom:12px" @click="$router.push(`/knowledge/${item.id}`)"><h3>{{item.title}}</h3><p>{{item.excerpt}}</p><el-tag v-for="tag in item.tags" :key="tag" size="small">{{tag}}</el-tag></el-card></section></div></template>
